"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

import "./playful-bounce.css";

export type PlayfulBounceControls = { play: () => void };
export type PlayfulBounceProps = React.ComponentProps<"span"> & {
  /** Hover is limited to fine pointers. Use a real button child for click. */
  trigger?: "hover" | "click" | "manual";
  /** Play once after mounting. */
  autoPlay?: boolean;
  /** Total duration in milliseconds. */
  duration?: number;
  /** Imperative playback; ref remains the root DOM node. */
  controlsRef?: React.Ref<PlayfulBounceControls>;
  targetClassName?: string;
};

export function PlayfulBounce({
  children,
  className,
  targetClassName,
  trigger = "hover",
  autoPlay = false,
  duration = 1500,
  controlsRef,
  onClick,
  onPointerEnter,
  ...props
}: PlayfulBounceProps) {
  const targetRef = React.useRef<HTMLSpanElement>(null);
  const play = React.useCallback(() => {
    const target = targetRef.current;
    if (
      !target ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches
    )
      return;
    // Keep the current choreography intact when triggers arrive mid-flight.
    target.dataset.playing = "true";
  }, []);

  React.useImperativeHandle(controlsRef, () => ({ play }), [play]);

  React.useEffect(() => {
    const preference = window.matchMedia("(prefers-reduced-motion: reduce)");
    const target = targetRef.current;
    const stop = () => {
      if (target) delete target.dataset.playing;
    };
    const onPreferenceChange = () => {
      if (preference.matches) stop();
    };
    preference.addEventListener("change", onPreferenceChange);
    if (autoPlay) play();
    return () => {
      preference.removeEventListener("change", onPreferenceChange);
      stop();
    };
  }, [autoPlay, play]);

  const durationStyle = {
    "--playful-bounce-duration": `${Number.isFinite(duration) ? Math.max(1, duration) : 1500}ms`,
  } as React.CSSProperties;

  return (
    <span
      {...props}
      data-slot="playful-bounce"
      className={cn("inline-flex", className)}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented && trigger === "click") play();
      }}
      onPointerEnter={(event) => {
        onPointerEnter?.(event);
        if (
          !event.defaultPrevented &&
          trigger === "hover" &&
          window.matchMedia("(hover: hover) and (pointer: fine)").matches
        )
          play();
      }}
    >
      <span
        ref={targetRef}
        data-slot="playful-bounce-sway"
        className="playful-bounce-sway"
        style={durationStyle}
        onAnimationEnd={(event) => {
          // The sway and the first hop end before the second hop lands.
          const sway = event.currentTarget;
          const running = sway
            .getAnimations?.({ subtree: true })
            .some((animation) => animation.playState !== "finished");
          if (!running) delete sway.dataset.playing;
        }}
      >
        <span
          data-slot="playful-bounce-target"
          className={cn("playful-bounce-target", targetClassName)}
        >
          {children}
        </span>
      </span>
    </span>
  );
}

/*
 * 海老ダンス choreography at its reference 1.5s: the wrapper sways for 1.3s
 * after 0.1s, while the inner hops twice for 0.7s each, 0.8s apart.
 * --playful-bounce-duration scales every time proportionally.
 */
.playful-bounce-sway,
.playful-bounce-target {
  display: inline-flex;
  transform-origin: bottom center;
}

/* The reference rests on the sway keyframes' 10deg lean. */
.playful-bounce-sway {
  rotate: 10deg;
}

.playful-bounce-sway[data-playing="true"] {
  animation: playful-bounce-sway calc(var(--playful-bounce-duration) * 13 / 15)
    ease-in-out calc(var(--playful-bounce-duration) / 15) both;
}

.playful-bounce-sway[data-playing="true"] > .playful-bounce-target {
  animation:
    playful-bounce-jump calc(var(--playful-bounce-duration) * 7 / 15)
      ease-in-out 0s both,
    playful-bounce-jump calc(var(--playful-bounce-duration) * 7 / 15)
      ease-in-out calc(var(--playful-bounce-duration) * 8 / 15) forwards;
}

@keyframes playful-bounce-jump {
  0%,
  20% {
    translate: 0 0;
  }
  50% {
    translate: 0 -30%;
  }
  80%,
  100% {
    translate: 0 0;
  }

  0% {
    scale: 1 1;
  }
  20% {
    scale: 1.08 0.9;
  }
  50% {
    scale: 1 1.1;
  }
  80% {
    scale: 1.08 0.9;
  }
  100% {
    scale: 1 1;
  }
}

@keyframes playful-bounce-sway {
  from,
  to {
    rotate: 10deg;
  }
  45%,
  55% {
    rotate: -10deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .playful-bounce-sway[data-playing="true"],
  .playful-bounce-sway[data-playing="true"] > .playful-bounce-target {
    animation: none;
  }
}
